#!/bin/bash
# autogenerated eqnx run script for:
# - eqnx: ../eqnx
# - prog: zrun.esx
# - conf: ../config.lua
# - psrc: ./zig-out/lib/
# - root: $HOME

HERE="/home/hugo/code/eqnx/zrun_eqnx/"
EQNX="$(which "../eqnx" || echo "$HERE/../eqnx")"
PROG="$HERE/zrun.esx"
CONF="$HERE/../config.lua"
PSRC="$HERE/./zig-out/lib/"

# ADD (manually): rebuild
cd "$HERE" && zig build || exit 1
# -----------------------

# Change cwd to root
cd "$HOME"

# Run
"$EQNX" -p "$PROG" -c "$CONF" -s "$PSRC" --size="600x400"
